func effortsOffered(host, def string) []string {
	efforts := hostEfforts[host]
	if len(efforts) <= maxOfferedEfforts {
		return efforts
	}
	end := maxOfferedEfforts
	if i := slices.Index(efforts, def); i >= end {
		end = i + 1
	}
	return efforts[end-maxOfferedEfforts : end]
}

